:host {
    display: block;
    --blue: #0176d3;
    --blue-ink: #0b5cab;
    --blue-soft: #eef4ff;
    --ink: #181818;
    --ink-2: #444444;
    --muted: #5c5c5c;
    --line: #e5e5e5;
    --ground: #f3f3f3;
}

.guide {
    max-width: 1200px;
    padding: 4px 0 32px;
    color: var(--ink);
    font-size: 14px;
    line-height: 1.5;
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.top {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: flex-end;
    gap: 12px;
}

.title { margin: 0; font-size: 22px; font-weight: 700; line-height: 1.25; }
.sub, .muted { margin: 4px 0 0; color: var(--muted); }
.small { font-size: 12.5px; }
.h2 { margin: 0; font-size: 17px; font-weight: 700; }
.intro { margin: 0; color: var(--ink-2); max-width: 75ch; }
.intro-art { max-width: 760px; }
.top-actions, .row-actions, .foot-right { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }

.card {
    background: #ffffff;
    border: 1px solid var(--line);
    border-radius: 12px;
    padding: 20px;
}

.error { color: #ba0517; }

/* buttons */
.btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: 36px;
    padding: 0 14px;
    border: 1px solid #c9c9c9;
    border-radius: 6px;
    background: #ffffff;
    color: var(--blue-ink);
    font: inherit;
    font-weight: 600;
    text-decoration: none;
    cursor: pointer;
    white-space: nowrap;
}
.btn:hover { background: #f7f9fc; text-decoration: none; }
.btn:focus-visible, .role-btn:focus-visible, .rail-item:focus-visible, .link-btn:focus-visible { outline: 2px solid var(--blue); outline-offset: 2px; }
.btn[disabled] { color: #939393; cursor: default; background: #ffffff; }
.btn-brand { background: var(--blue); border-color: var(--blue); color: #ffffff; }
.btn-brand:hover { background: #0b5cab; color: #ffffff; }
.btn-quiet { border-color: transparent; color: var(--muted); }
.btn-sm { height: 30px; padding: 0 10px; font-size: 13px; }
.btn-icon { margin-right: 2px; }

/* role picker */
.roles { display: flex; flex-wrap: wrap; gap: 8px; }
.role-btn {
    display: inline-flex;
    align-items: center;
    height: 36px;
    padding: 0 16px;
    border-radius: 18px;
    border: 1px solid #c9c9c9;
    background: #ffffff;
    color: var(--ink);
    font: inherit;
    cursor: pointer;
}
.role-btn.on { background: var(--blue); border-color: var(--blue); color: #ffffff; font-weight: 700; }
.role-dot { width: 8px; height: 8px; border-radius: 4px; margin-right: 8px; background: #747474; }
.role-sfUser .role-dot { background: #7526e3; }
.role-gitUser .role-dot { background: #dd7a01; }
.role-sfAdmin .role-dot { background: var(--blue); }
.role-gitAdmin .role-dot { background: #2e844a; }
.role-approver .role-dot { background: #ba0517; }
.role-types .role-dot { background: #0b827c; }
.role-demo .role-dot { background: #dd7a01; }
.role-btn.on .role-dot { background: #ffffff; }

/* two-column layout */
.layout { display: flex; flex-wrap: wrap; gap: 20px; align-items: flex-start; }
.rail { flex: 1 1 250px; max-width: 320px; padding: 16px; display: flex; flex-direction: column; gap: 12px; }
.step-card { flex: 999 1 560px; min-width: 0; padding: 24px; display: flex; flex-direction: column; gap: 14px; }

.prog-label { display: flex; justify-content: space-between; font-size: 13px; color: var(--ink-2); }
.prog-bar { height: 6px; background: var(--line); border-radius: 3px; margin-top: 8px; overflow: hidden; }
.prog-fill { height: 6px; background: #2e844a; border-radius: 3px; transition: width 0.2s; }

.rail-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 4px; }
.rail-item {
    width: 100%;
    display: flex;
    gap: 10px;
    align-items: center;
    text-align: left;
    padding: 8px 10px;
    border-radius: 8px;
    border: 1px solid transparent;
    background: transparent;
    color: var(--ink);
    font: inherit;
    cursor: pointer;
}
.rail-item:hover { background: #f7f9fc; }
.rail-item.current { border-color: var(--blue); background: var(--blue-soft); }
.rail-text { font-weight: 600; min-width: 0; }
.dot {
    flex: none;
    width: 26px;
    height: 26px;
    border-radius: 13px;
    border: 1.5px solid #c9c9c9;
    background: #ffffff;
    color: var(--ink-2);
    font-size: 12px;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
}
.dot-cur { background: var(--blue); border-color: var(--blue); color: #ffffff; }
.dot-done { background: #2e844a; border-color: #2e844a; color: #ffffff; }

/* step card */
.meta { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.of { font-size: 13px; color: var(--muted); }
.done-tag { font-size: 12px; font-weight: 700; color: #194e31; background: #ebf7e6; border-radius: 10px; padding: 1px 8px; }
.step-title { margin: 0; font-size: 20px; font-weight: 700; line-height: 1.3; }
.where { margin: 0; font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 12.5px; color: var(--muted); }
.step-body { display: flex; flex-wrap: wrap; gap: 24px; align-items: flex-start; }
.step-art { flex: 0 1 360px; margin: 0; background: #f7f9fc; border: 1px solid var(--line); border-radius: 10px; padding: 12px; }
.step-text { flex: 1 1 300px; min-width: 0; display: flex; flex-direction: column; gap: 12px; }
.actions, .numbered { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 10px; }
.actions li, .numbered li { display: flex; gap: 10px; align-items: flex-start; }
.n {
    flex: none;
    width: 22px;
    height: 22px;
    border-radius: 11px;
    background: var(--blue-soft);
    color: var(--blue-ink);
    font-size: 12px;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
}
.card-foot { display: flex; justify-content: space-between; gap: 12px; flex-wrap: wrap; border-top: 1px solid var(--line); padding-top: 16px; margin-top: 4px; }

.tip, .handoff {
    margin: 0;
    padding: 10px 12px;
    border-radius: 8px;
    font-size: 13px;
    display: flex;
    gap: 8px;
    align-items: flex-start;
}
.tip { background: #f3f9ff; color: #1b3d5f; }
.handoff-in { background: #fef1cd; color: #5c3a00; }
.handoff-out { background: #ebf7e6; color: #194e31; }

.code-block {
    margin: 0;
    padding: 12px;
    background: #1b1f24;
    color: #e6edf3;
    border-radius: 8px;
    font-family: ui-monospace, Menlo, Consolas, monospace;
    font-size: 12px;
    line-height: 1.6;
    white-space: pre-wrap;
    word-break: break-word;
}

.table-wrap { overflow-x: auto; border-radius: 8px; }
.table-wrap td { white-space: normal; }
.mono { font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 12.5px; }
.strong { font-weight: 700; }

/* badges */
.badge { display: inline-block; padding: 2px 10px; border-radius: 12px; font-size: 12px; font-weight: 700; white-space: nowrap; }
.badge-gitAdmin { background: #ebf7e6; color: #194e31; }
.badge-sfAdmin { background: var(--blue-soft); color: var(--blue-ink); }
.badge-sfUser { background: #f3f0ff; color: #5a1ba9; }
.badge-gitUser { background: #fef1cd; color: #8c4b02; }
.badge-approver { background: #fef1ee; color: #8e030f; }
.badge-types { background: #e3f7f5; color: #054b47; }
.badge-demo { background: #fef1cd; color: #5c3a00; }

/* setup order timeline */
.order-head { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: flex-end; gap: 12px; margin-bottom: 12px; }
.legend { display: flex; flex-wrap: wrap; gap: 14px; font-size: 12px; color: var(--ink-2); }
.legend > span { display: inline-flex; align-items: center; gap: 6px; }
.lg { width: 10px; height: 10px; border-radius: 5px; display: inline-block; }
.lg-gitAdmin { background: #2e844a; }
.lg-sfAdmin { background: var(--blue); }
.lg-sfUser { background: #7526e3; }
.timeline { list-style: none; margin: 0; padding: 0; }
.tl-row { display: flex; gap: 14px; align-items: stretch; }
.tl-rail { display: flex; flex-direction: column; align-items: center; width: 32px; }
.tl-dot {
    flex: none;
    width: 30px;
    height: 30px;
    border-radius: 15px;
    color: #ffffff;
    font-size: 12px;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
}
.tl-gitAdmin { background: #2e844a; }
.tl-sfAdmin { background: var(--blue); }
.tl-sfUser { background: #7526e3; }
.tl-line { flex: 1; width: 2px; min-height: 14px; background: var(--line); }
.tl-end { background: transparent; }
.tl-body { flex: 1; min-width: 0; padding: 4px 0 14px; display: flex; flex-wrap: wrap; gap: 6px 14px; align-items: baseline; }
.tl-title { flex: 1 1 280px; font-weight: 700; }
.tl-handoff { flex: 1 1 100%; }

.link-btn { background: none; border: 0; padding: 0; color: var(--blue-ink); text-align: left; cursor: pointer; font: inherit; }
.link-btn:hover { text-decoration: underline; }

.edit-card { border-color: var(--blue); display: flex; flex-direction: column; gap: 12px; }
